create table if not exists meeting_participants (id uuid primary key default gen_random_uuid(), meeting_id uuid references meetings(id) on delete cascade, user_id uuid, role text not null, status text default 'invited', joined_at timestamptz, left_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now()); alter table meeting_participants enable row level security; create index if not exists idx_meeting_participants_meeting on meeting_participants(meeting_id);
